sys_script_include.script:
var FetchManagerDetails = Class.create();
FetchManagerDetails.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getDetails: function() {
        var userId = this.getParameter('sysparm_user_id');
        var userGR = new GlideRecord('PettyCashUsers');

        if (userGR.get(userId) && userGR.manager  ) {
            var managerGR = new GlideRecord('PettyCashUsers');
            if (managerGR.get(userGR.manager)) {
                return JSON.stringify({
                    name: managerGR.name.toString(),
                    email: managerGR.email.toString()
                });
            }
        }
        return JSON.stringify({
            name: '',
            email: ''
        });
    }
});
